class Program
{
    static void Main()
    {
        (var x1, x1) = new A();
        (x2, var x2) = new A();
        (var x3, (var y3, x3)) = new B();
        (x4, (var y4, var x4)) = new B();
    }
}

class A
{
    public void Deconstruct(out int a, out string b)
    {
        a = 1;
        b = "hello";
    }
}

class B
{
    public void Deconstruct(out int a, out (string b, bool c) tuple)
    {
        a = 1;
        tuple = ("hello", true);
    }
}

